css:
.br { display: flex; flex-wrap: wrap; gap: .75rem; margin-top: 1rem; }
.br a { text-decoration: none; }
.br__btn { display: inline-flex; align-items: center; min-height: 48px; padding: .7rem 1.4rem; border: 2px solid currentColor; border-radius: 999px; font-weight: 700; font-size: 1rem; color: var(--os-color-heading); }
.br__btn:hover { background: color-mix(in srgb, var(--os-color-text) 8%, transparent); }
